mapper.select:
SELECT board_number
FROM tb_board
WHERE region_name = #{regionName}
  AND board_category_name = #{boardCategoryName}
  AND post_category_name = #{postCategoryName}
    LIMIT 1

mapper.update:
UPDATE tb_post
SET view_count = view_count + 1
WHERE post_number = #{postNumber}

mapper.delete:
DELETE FROM tb_post_recommend
WHERE 1=1
AND post_number = #{postNumber}
AND user_number = #{userNumber}

mapper.select:
    /* 추천 안했으면 false , 했으면 true */
	  SELECT EXISTS (
	    SELECT 1
	    FROM tb_post_recommend
	    WHERE post_number = #{postNumber}
	      AND user_number = #{userNumber}
	  ) AS recommended_by_me

SELECT COUNT(*)
FROM tb_post_recommend
WHERE post_number = #{postNumber}
